static inline int bf_web_route_dispatch(const BfRequest *request) {
    return bf_route_dispatch(bf_web_routes, sizeof(bf_web_routes) / sizeof(bf_web_routes[0]), request);
}
static inline int bf_web_route_ask(BfRouteOwner owner, const BfRequest *request) {
    return bf_route_ask(bf_web_routes, sizeof(bf_web_routes) / sizeof(bf_web_routes[0]), owner, request);
}
/* The not-found tail: 404 with the nearest declared pages and records. */
static int bf_web_route_not_found(const char *path) {
    return bf_route_not_found_page(bf_web_routes, sizeof(bf_web_routes) / sizeof(bf_web_routes[0]),
                                   bf_web_route_suggest_sets, sizeof(bf_web_route_suggest_sets) / sizeof(bf_web_route_suggest_sets[0]) - 1,
                                   &bf_web_route_semantic, path);
}
